<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import DiagnosticModuleTabs from '../DiagnosticModuleTabs.vue';
import TripEditor from './TripEditor.vue';
import TripClose from './TripClose.vue';
import type {TripCatalog,TripRecord} from '~~/shared/types/diagnostic-trips';
import {tripDateLabel} from '~~/shared/utils/diagnostic-trips';
const rows=ref<TripRecord[]>([]),catalog=ref<TripCatalog>({contracts:[],executors:[],participants:[],warning:null}),rights=ref({CREATE:false,UPDATE:false,DELETE:false}),busy=ref(false),error=ref(''),search=ref(''),status=ref('ALL'),selectedId=ref<number|null>(null),editor=ref(false),readOnly=ref(true),editing=ref<TripRecord|null>(null),closing=ref<TripRecord|null>(null);
const removing=ref<TripRecord|null>(null),deleteBusy=ref(false),notice=ref('');
const sortKey=ref('start'),descending=ref(true);let generation=0;
const columns=[{key:'number',label:'ID'},{key:'start',label:'Дата начала'},{key:'finish',label:'Дата окончания'},{key:'contractNumber',label:'Договор'},{key:'executor',label:'Исполнитель'},{key:'members',label:'Участники'},{key:'roads',label:'Автодорога'},{key:'locations',label:'Расположение (км+м)'}];
function value(r:TripRecord,k:string){if(k==='members')return r.participants.map(p=>p.name).join(', ');if(k==='roads')return [...new Set(r.structures.map(s=>s.roadName))].join('; ');if(k==='locations')return r.noStructures?'Без указания сооружений'+(r.destination?' · '+r.destination:''):r.structures.map(s=>s.location+(s.additionalId?' · '+s.additionalId:'')).join('; ');return String(r[k as keyof TripRecord]??'');}
const visible=computed(()=>rows.value.filter(r=>(status.value==='ALL'||r.status===status.value)&&[...columns.map(c=>value(r,c.key)),tripDateLabel(r.start),tripDateLabel(r.finish),r.note,r.assignment,r.structures.map(s=>s.code).join(' ')].join(' ').toLocaleLowerCase('ru').includes(search.value.trim().toLocaleLowerCase('ru'))).sort((a,b)=>value(a,sortKey.value).localeCompare(value(b,sortKey.value),'ru',{numeric:true})*(descending.value?-1:1)));
const selected=computed(()=>visible.value.find(r=>r.id===selectedId.value)||null);
function sort(k:string){if(sortKey.value===k)descending.value=!descending.value;else{sortKey.value=k;descending.value=false;}}
async function load(){const g=++generation;busy.value=true;error.value='';try{const [data,options,create,update,remove]=await Promise.all([$fetch<TripRecord[]>('/api/diagnostic/trips'),$fetch<TripCatalog>('/api/diagnostic/trips/catalog'),$fetch<{allowed:boolean}>('/api/access/check',{query:{resource:'diagnostic.contracts',action:'CREATE'}}),$fetch<{allowed:boolean}>('/api/access/check',{query:{resource:'diagnostic.contracts',action:'UPDATE'}}),$fetch<{allowed:boolean}>('/api/access/check',{query:{resource:'diagnostic.contracts',action:'DELETE'}})]);if(g!==generation)return;rows.value=data;catalog.value=options;rights.value={CREATE:create.allowed,UPDATE:update.allowed,DELETE:remove.allowed};}catch(e:any){if(g===generation){rows.value=[];rights.value={CREATE:false,UPDATE:false,DELETE:false};error.value=e?.data?.message||'Не удалось загрузить командировки. Проверьте установку обновления и соединение.';}}finally{if(g===generation)busy.value=false;}}
onMounted(load);onBeforeUnmount(()=>generation++);
function create(){editing.value=null;readOnly.value=false;editor.value=true;}
async function open(edit=false){if(!selected.value)return;try{editing.value=await $fetch<TripRecord>('/api/diagnostic/trips/'+selected.value.id);readOnly.value=!edit||!rights.value.UPDATE||editing.value.status==='COMPLETED';editor.value=true;}catch(e:any){error.value=e?.data?.message||'Не удалось открыть командировку.';}}
async function closeTrip(){if(!selected.value)return;try{closing.value=await $fetch<TripRecord>('/api/diagnostic/trips/'+selected.value.id);}catch(e:any){error.value=e?.data?.message||'Не удалось открыть командировку.';}}
function saved(row:TripRecord){notice.value=row.emails?.some(e=>['FAILED','UNKNOWN'].includes(e.status))?'Командировка сохранена. Есть ошибки почтовых уведомлений — откройте карточку для подробностей.':row.emails?.some(e=>e.status==='PENDING')?'Командировка сохранена. Почтовые уведомления поставлены в очередь.':'Командировка сохранена.';editor.value=false;closing.value=null;selectedId.value=row.id;void load();}
async function askDelete(){if(!selected.value)return;error.value='';try{removing.value=await $fetch<TripRecord>('/api/diagnostic/trips/'+selected.value.id);}catch(e:any){error.value=e?.data?.message||'Не удалось открыть командировку.';}}
async function removeTrip(){if(!removing.value||deleteBusy.value)return;deleteBusy.value=true;error.value='';try{const result=await $fetch<{worksDeleted:number}>('/api/diagnostic/trips/'+removing.value.id,{method:'DELETE',headers:{'x-space-diagnostic':'1'},body:{version:removing.value.version,confirmed:true}});notice.value=`Командировка удалена. Удалено связанных работ: ${result.worksDeleted}.`;removing.value=null;selectedId.value=null;await load();}catch(e:any){error.value=e?.data?.message||'Не удалось удалить командировку.';}finally{deleteBusy.value=false;}}
async function retryMail(){if(!selected.value||!window.confirm('Повторить неуспешные уведомления? Сначала проверьте журнал SMTP: при неизвестном результате письмо могло быть доставлено.'))return;try{const r=await $fetch<{queued:number}>(`/api/diagnostic/trips/${selected.value.id}/retry-emails`,{method:'POST',headers:{'x-space-diagnostic':'1'},body:{confirmed:true}});notice.value=`Повторно поставлено в очередь: ${r.queued}.`;await load();}catch(e:any){error.value=e?.data?.message||'Не удалось повторить отправку.';}}
function exportCsv(){const cell=(s:string)=>'"'+(/^(?:\s*[=+\-@]|[\t\r\n])/.test(s)?"'"+s:s).replaceAll('"','""')+'"';const lines=[columns.map(c=>cell(c.label)).join(';'),...visible.value.map(r=>columns.map(c=>cell(['start','finish'].includes(c.key)?tripDateLabel(value(r,c.key)):value(r,c.key))).join(';'))];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Командировки.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template><section class="odis-trips">
 <DiagnosticModuleTabs active="trips"><UDropdownMenu :items="[{label:'Добавить командировку',disabled:!rights.CREATE,onSelect:create},{label:'Изменить командировку',disabled:!selected||!rights.UPDATE||selected.status==='COMPLETED',onSelect:()=>open(true)},{label:'Закрыть командировку',disabled:!selected||!rights.UPDATE||selected.status==='COMPLETED',onSelect:closeTrip},{label:'Сформировать отчёт (CSV)',disabled:!visible.length,onSelect:exportCsv}]"><button class="diagnostic-quick">Быстрые действия <Icon name="lucide:chevron-down"/></button></UDropdownMenu><input v-model="search" class="trip-search" placeholder="Поиск командировок" aria-label="Поиск командировок"/></DiagnosticModuleTabs>
 <div class="trip-workspace"><div class="trip-workspace-title"><h1>Командировки</h1><label>Статус<select v-model="status"><option value="ALL">Все</option><option value="PLANNED">Запланированные</option><option value="COMPLETED">Завершённые</option></select></label><span class="trip-legend"><span class="trip-green-dot"></span>Завершённые</span><button :disabled="busy" @click="load">Обновить</button></div><p v-if="error" class="trip-error" role="alert">{{error}}</p>
 <p v-if="notice" class="trip-notice" role="status">{{notice}}</p><section v-if="removing" class="trip-delete-confirm" role="alert"><strong>Удалить командировку {{removing.number}}?</strong><p>Из списков будут удалены командировка и связанные с ней работы по сооружениям. Ожидающие уведомления будут отменены.</p><div><button class="trip-danger" :disabled="deleteBusy" @click="removeTrip">{{deleteBusy?'Удаление…':'Удалить командировку и работы'}}</button><button :disabled="deleteBusy" @click="removing=null">Отменить</button></div></section><div class="trip-register"><aside class="trip-actions"><button :disabled="busy||!rights.CREATE" @click="create"><Icon name="lucide:clipboard-plus"/>Добавить</button><button :disabled="busy||!selected" @click="open()"><Icon name="lucide:eye"/>Просмотр</button><button :disabled="busy||!selected||!rights.UPDATE||selected.status==='COMPLETED'" @click="open(true)"><Icon name="lucide:pencil"/>Изменить</button><button :disabled="busy||!selected||!rights.UPDATE||selected.status==='COMPLETED'" @click="closeTrip"><Icon name="lucide:calendar-check"/>Закрыть командировку</button><button class="trip-danger" :disabled="busy||!selected||!rights.DELETE" @click="askDelete"><Icon name="lucide:trash-2"/>Удалить</button><button v-if="selected?.emails?.some(e=>['FAILED','UNKNOWN'].includes(e.status))" :disabled="busy||!rights.UPDATE" @click="retryMail">Повторить уведомления</button><button :disabled="!visible.length" @click="exportCsv"><Icon name="lucide:file-spreadsheet"/>Отчёт CSV</button></aside>
 <div class="trip-table-scroll trip-register-table" :aria-busy="busy"><table><thead><tr><th v-for="c in columns" :key="c.key" :aria-sort="sortKey===c.key?(descending?'descending':'ascending'):'none'"><button @click="sort(c.key)">{{c.label}} <span v-if="sortKey===c.key">{{descending?'↓':'↑'}}</span></button></th></tr></thead><tbody><tr v-if="busy"><td colspan="8">Загрузка командировок…</td></tr><template v-else><tr v-for="r in visible" :key="r.id" :class="{'is-completed':r.status==='COMPLETED','is-selected':selectedId===r.id}" @click="selectedId=r.id" @dblclick="selectedId=r.id;open()"><td><button :aria-pressed="selectedId===r.id" @click.stop="selectedId=r.id;open()">{{r.number}}</button></td><td>{{tripDateLabel(r.start)}}</td><td>{{tripDateLabel(r.finish)}}</td><td>{{r.contractNumber}}</td><td>{{r.executor}}</td><td v-for="k in ['members','roads','locations']" :key="k" :title="value(r,k)">{{value(r,k)}}</td></tr><tr v-if="!visible.length"><td colspan="8">{{rows.length?'Командировки по заданным условиям не найдены.':'Командировок пока нет. Добавьте новую или выполните импорт.'}}</td></tr></template></tbody></table></div></div><div class="trip-register-summary">Показано: {{visible.length}} из {{rows.length}} · Запланировано: {{rows.filter(r=>r.status==='PLANNED').length}} · Завершено: {{rows.filter(r=>r.status==='COMPLETED').length}}</div>
 </div><TripEditor v-if="editor" :trip="editing" :catalog="catalog" :read-only="readOnly" @close="editor=false" @saved="saved"/><TripClose v-if="closing" :trip="closing" :catalog="catalog" @close="closing=null" @saved="saved"/>
</section></template>
<style src="~/assets/css/diagnostic-trips.css"></style>
